import type { TimeAnimationOptions } from '@wix/motion';

import type {
  Animation,
  Animation_Easing,
  LoopAnimation,
} from './../../ricos-schema/next-schema/index.js';
import { Animation_Type } from './../../ricos-schema/next-schema/index.js';

import type { LoopEffectConfig } from './loop-effects.js';
import { LOOP_EFFECTS } from './loop-effects.js';

const SCREAMING_ENUM = /^[A-Z][A-Z_]*$/;

// Schema enum params are SCREAMING_SNAKE; motion literals are kebab-lower — the same
// shape-test mapping as the entrance converter, and the same caveat: every string param
// the loop union declares today (`direction`) is a schema enum. Add a per-key mapping
// the moment a free-text string param appears.
const toMotionParam = (value: unknown): unknown =>
  typeof value === 'string' && SCREAMING_ENUM.test(value)
    ? value.toLowerCase().replace(/_/g, '-')
    : value;

/**
 * Converts a stored `Animation`'s loop family into `@wix/motion` time-animation options.
 * The loop twin of `toMotionOptions` (entrance) — same fail-open contract: returns null
 * for anything this build can't map, and callers must not leave the node broken on null.
 *
 * `iterations` defaults to motion's Infinity sentinel (`0`); the editor preview passes a
 * small finite count instead so the group's `finished` promise actually settles.
 */
export const toLoopMotionOptions = (
  animation: Animation,
  { iterations = 0 }: { iterations?: number } = {}
): TimeAnimationOptions | null => {
  if (animation.type !== Animation_Type.VIEW) {
    return null;
  }
  const loop: LoopAnimation | undefined = animation.loop;
  if (!loop?.effect) {
    return null;
  }
  const { effect, duration, iterationDelay } = loop;
  const { type, ...storedParams } = effect;
  const config = LOOP_EFFECTS[type] as LoopEffectConfig | undefined;
  if (!config) {
    return null;
  }
  // stored values win, but an explicit `undefined` key must not clobber the default
  const params: Record<string, unknown> = {
    ...config.params,
    ...Object.fromEntries(Object.entries(storedParams).filter(([, value]) => value !== undefined)),
  };
  // Motion style resolves per effect (see LoopEasingMap): to a curve on the group's own
  // `easing` option, or to the preset's `intensity` param. An easing this build doesn't
  // know — or one on an effect without a map — is dropped, like the entrance converter.
  const { easing, ...effectParams } = params as { easing?: Animation_Easing };
  const curve =
    easing && config.easingMap?.kind === 'curve' ? config.easingMap.values[easing] : undefined;
  const intensity =
    easing && config.easingMap?.kind === 'intensity' ? config.easingMap.values[easing] : undefined;

  return {
    namedEffect: {
      type: config.preset,
      ...Object.fromEntries(
        Object.entries(effectParams).map(([key, value]) => [key, toMotionParam(value)])
      ),
      ...(intensity !== undefined ? { intensity } : {}),
      // iterationDelay is a namedEffect param, not a group option: every ongoing preset
      // inflates its own duration to `duration + iterationDelay` and compresses the
      // motion into the leading fraction, holding the final keyframe for the rest
      iterationDelay: iterationDelay ?? config.iterationDelay,
    },
    // `||`, not `??` — a stored 0 would otherwise become a 1ms animation (see toMotionOptions)
    duration: duration || config.duration,
    // 0 is motion's Infinity sentinel (`iterations === 0 ? Infinity : iterations || 1`);
    // an undefined would silently mean "play once"
    iterations,
    ...(curve ? { easing: curve } : {}),
    // same rationale as entrance: hold first/last keyframe around playback so preview
    // replays never flash the unanimated state (only from play() onwards — an idle
    // animation contributes nothing)
    fill: 'both',
  };
};
