import type {
  Animation_Easing,
  LoopEffect,
  LoopEffect_Type,
} from './../../ricos-schema/next-schema/index.js';

/** The optional params a given loop effect owns, with its discriminant removed. */
export type LoopEffectParams<T extends LoopEffect_Type> = Omit<
  Extract<LoopEffect, { type: T }>,
  'type'
>;

/**
 * How an effect's motion style (`Animation_Easing`) reaches motion. The ongoing presets split
 * structurally: four map it to an easing curve, six map it to the preset's `intensity` number
 * (the exact six that declare `intensity` in `@wix/motion-presets`), and three (Breathe, Cross,
 * Flash) have no motion style at all — their schema variants declare no `easing`, so they carry
 * no map here.
 */
export type LoopEasingMap =
  | { kind: 'curve'; values: Record<Animation_Easing, string> }
  | { kind: 'intensity'; values: Record<Animation_Easing, number> };

export type LoopEffectConfig<T extends LoopEffect_Type = LoopEffect_Type> = {
  /** `@wix/motion-presets` preset this effect plays — must match a key registered in `motion-runtime`. */
  preset: string;
  /** Default duration of one iteration in ms. Motion has no tuned default — a missing duration is coerced to 1ms. */
  duration: number;
  /** Default pause between iterations in ms (the classic editor's "Delay Between Loops"). */
  iterationDelay: number;
  /**
   * Defaults for the effect's own params — including `easing` (motion style) for the effects
   * that expose one. Typed from the schema variant, so an effect that declares no `easing`
   * can't be given a motion-style default here.
   */
  params?: LoopEffectParams<T>;
  /** Present exactly when the schema variant declares `easing` (see LoopEasingMap). */
  easingMap?: LoopEasingMap;
};

// Rotation loops read best at constant speed, so their gentle style is linear and the harder
// styles add acceleration; pendulum loops swing on a sine by nature. Both ladders end on
// backInOut (overshoot), matching the "INTENSE overshoots" promise of Animation_Easing.
const ROTATION_CURVES: Record<Animation_Easing, string> = {
  GENTLE: 'linear',
  MODERATE: 'cubicInOut',
  INTENSE: 'backInOut',
};
const PENDULUM_CURVES: Record<Animation_Easing, string> = {
  GENTLE: 'sineInOut',
  MODERATE: 'cubicInOut',
  INTENSE: 'backInOut',
};

// Intensity ladders are anchored so the classic default power plays the exact intensity the
// Wix editor ships for that effect (e.g. Pulse: soft = 0, Poke: medium = 0.5, Bounce:
// soft = 0.3), stepping linearly up to the preset's hard limit of 1. Provisional pending a
// visual side-by-side with santa — retuning here is retroactive, since defaults are injected
// at play time and never stored.
const intensityLadder = (gentle: number, moderate: number, intense: number): LoopEasingMap => ({
  kind: 'intensity',
  values: { GENTLE: gentle, MODERATE: moderate, INTENSE: intense },
});
const curveLadder = (values: Record<Animation_Easing, string>): LoopEasingMap => ({
  kind: 'curve',
  values,
});

/**
 * The single source of truth for every ricos-owned loop-effect default.
 *
 * Mirrors santa-editor's `@wix/effects-kit` classic-editor config (same recipe as
 * `ENTRANCE_EFFECTS`): `duration` and `iterationDelay` come from each effect's classic schema
 * defaults, `params.direction` from its classic direction default, and `params.easing` from its
 * classic `power` default (soft → GENTLE, medium → MODERATE). The three effects without a
 * classic `power` key (Breathe, Cross, Flash) have no motion style.
 *
 * Defaults are injected at playback time rather than written into the document — see
 * `ENTRANCE_EFFECTS` for why.
 */
export const LOOP_EFFECTS: { [T in LoopEffect_Type]: LoopEffectConfig<T> } = {
  BOUNCE: {
    preset: 'Bounce',
    duration: 1200,
    iterationDelay: 1000,
    params: { easing: 'GENTLE' },
    easingMap: intensityLadder(0.3, 0.65, 1),
  },
  BREATHE: {
    preset: 'Breathe',
    duration: 4000,
    iterationDelay: 0,
    params: { direction: 'VERTICAL' },
  },
  CROSS: {
    preset: 'Cross',
    duration: 5000,
    iterationDelay: 0,
    params: { direction: 'RIGHT' },
  },
  FLASH: { preset: 'Flash', duration: 2000, iterationDelay: 0 },
  FLIP: {
    preset: 'Flip',
    duration: 5000,
    iterationDelay: 0,
    params: { direction: 'HORIZONTAL', easing: 'GENTLE' },
    easingMap: curveLadder(ROTATION_CURVES),
  },
  FOLD: {
    preset: 'Fold',
    duration: 3000,
    iterationDelay: 0,
    params: { direction: 'TOP', easing: 'MODERATE' },
    easingMap: curveLadder(PENDULUM_CURVES),
  },
  JELLO: {
    preset: 'Jello',
    duration: 1000,
    iterationDelay: 1000,
    params: { easing: 'GENTLE' },
    easingMap: intensityLadder(0.3, 0.65, 1),
  },
  POKE: {
    preset: 'Poke',
    duration: 1200,
    iterationDelay: 800,
    params: { direction: 'RIGHT', easing: 'MODERATE' },
    easingMap: intensityLadder(0, 0.5, 1),
  },
  PULSE: {
    preset: 'Pulse',
    duration: 1300,
    iterationDelay: 1000,
    params: { easing: 'GENTLE' },
    easingMap: intensityLadder(0, 0.5, 1),
  },
  RUBBER: {
    preset: 'Rubber',
    duration: 1000,
    iterationDelay: 2000,
    params: { easing: 'GENTLE' },
    easingMap: intensityLadder(0.5, 0.75, 1),
  },
  SPIN: {
    preset: 'Spin',
    duration: 7000,
    iterationDelay: 0,
    params: { direction: 'CLOCKWISE', easing: 'GENTLE' },
    easingMap: curveLadder(ROTATION_CURVES),
  },
  SWING: {
    preset: 'Swing',
    duration: 3500,
    iterationDelay: 0,
    params: { direction: 'TOP', easing: 'GENTLE' },
    easingMap: curveLadder(PENDULUM_CURVES),
  },
  WIGGLE: {
    preset: 'Wiggle',
    duration: 600,
    iterationDelay: 800,
    params: { easing: 'GENTLE' },
    easingMap: intensityLadder(0.5, 0.75, 1),
  },
};

/**
 * The loop effect's default motion style, or `undefined` when it has none. Reading `.easing`
 * off the params union isn't type-safe (only 10 of the 13 variants declare it), so go through here.
 */
export const defaultLoopEasingOf = (type: LoopEffect_Type): Animation_Easing | undefined =>
  (LOOP_EFFECTS[type].params as { easing?: Animation_Easing } | undefined)?.easing;
