import type { AnimationGroup } from '@wix/motion';

import type { Animation, Node } from './../../ricos-schema/next-schema/index.js';
import { getNodeAnimation } from './../../_shared/node-animation/get-node-animation.js';
import { hasEntranceAnimation } from './../../_shared/node-animation/has-entrance-animation.js';
import {
  getEntranceAnimation,
  getLoopAnimation,
  getPointerAnimation,
} from './../../_shared/node-animation/motion-runtime.js';

import { createPointerAnimationManager } from './pointer-animation-manager.js';

const hasLoopAnimation = (animation: Animation): boolean =>
  animation.type === 'VIEW' && Boolean(animation.loop?.effect);

/** Fraction of a node that must be on screen before its entrance plays. */
const ENTRANCE_THRESHOLD = 0.2;

// `0` has to be observed alongside ENTRANCE_THRESHOLD. A node taller than
// `rootHeight / ENTRANCE_THRESHOLD` can never reach a 0.2 intersection ratio, and with 0.2 as
// the only threshold the observer never notifies for such a node at all — not even when it
// fills the whole viewport — so it would stay hidden by the reveal CSS forever. With 0 in the
// list every node produces an entry the moment it touches the viewport, and `hasEntered`
// decides whether that entry is enough to play on.
const OBSERVER_THRESHOLDS = [0, ENTRANCE_THRESHOLD];

/**
 * Whether enough of the node is on screen to play its entrance. Normally that means
 * ENTRANCE_THRESHOLD of the node itself. A node too tall to ever reach that ratio plays on
 * first contact instead, because no further entry will arrive: its ratio stays between the two
 * thresholds for the node's entire pass through the viewport, and the observer only notifies on
 * a threshold crossing.
 */
const hasEntered = (entry: IntersectionObserverEntry): boolean => {
  if (entry.intersectionRatio >= ENTRANCE_THRESHOLD) {
    return true;
  }
  const rootHeight = entry.rootBounds?.height ?? window.innerHeight;
  return entry.boundingClientRect.height > rootHeight / ENTRANCE_THRESHOLD;
};

const reveal = (element: HTMLElement) => element.setAttribute('data-ricos-entered', '');

/**
 * Entrance `finished` promises handed across runtime instances. A content swap
 * re-creates the runtime, but the animated DOM elements — and the WAAPI entrance
 * animations playing on them — survive, and dispose deliberately leaves a started
 * entrance running (see the cleanup comment below). The next runtime has no group
 * handle for it, so the promise is parked here, keyed by element (a WeakMap entry
 * dies with its element). Written only once an entrance actually starts playing —
 * a dispose-before-ready entrance never plays, and parking its forever-pending
 * `finished` would stall the next runtime's loop for good.
 */
const entranceFinishedByElement = new WeakMap<HTMLElement, Promise<unknown>>();

const collectAnimations = (nodes: Node[], byNodeId: Map<string, Animation>): void =>
  nodes.forEach(node => {
    const animation = getNodeAnimation(node);
    if (animation && node.id) {
      byNodeId.set(node.id, animation);
    }
    collectAnimations(node.nodes ?? [], byNodeId);
  });

/**
 * Client-only animation playback (the lazy half of <NodeAnimations>). VIEW nodes
 * are observed: on first viewport intersection the node is revealed, its entrance
 * plays exactly once and its loop starts (either directly or chained onto the
 * entrance's finish). POINTER nodes skip observation and register with the pointer
 * manager, which drives them from a single window pointermove listener. Returns a
 * cleanup function.
 */
export const initNodeAnimations = (root: HTMLElement, nodes: Node[]): (() => void) => {
  const byNodeId = new Map<string, Animation>();
  collectAnimations(nodes, byNodeId);

  const elements = Array.from(root.querySelectorAll<HTMLElement>('[data-ricos-animation]'));

  // Under reduced motion the hide CSS never applied (it's media-gated), so
  // nothing is hidden — just mark everything entered and skip playback. Loops
  // included: motion itself refuses infinite-iteration animations under
  // reduced motion, so there is nothing meaningful to degrade to.
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
    elements.forEach(reveal);
    return () => {};
  }

  const liveLoops = new Set<AnimationGroup>();
  // created on the first POINTER node — a document without mouse effects never
  // pays for the window listener
  let pointerManager: ReturnType<typeof createPointerAnimationManager> | null = null;
  let disposed = false;

  // Motion's play() defers the real WAAPI start to `ready` (next frame) with no
  // cancelled-check in its continuation: cleanup's cancel() landing in that window no-ops
  // on the still-idle animations, and the pending continuation then revives them — for a
  // loop, an infinite animation no remaining handle can stop. Start only once ready, and
  // only while the runtime is still live. The play() catch keeps a teardown AbortError
  // from surfacing as an unhandled rejection. `onPlay` runs exactly when playback really
  // begins — the entrance path uses it to publish its cross-runtime handoff (see
  // entranceFinishedByElement).
  const playWhileLive = (group: AnimationGroup, onPlay?: () => void) =>
    group.ready
      .then(() => {
        if (!disposed) {
          onPlay?.();
          group.play().catch(() => {});
        }
      })
      .catch(() => {});

  // An infinite loop's `finished` never settles, so the group stays in liveLoops for
  // the runtime's whole life — exactly what cleanup's cancel() sweep needs to stop it.
  // Entrances are deliberately not tracked for cancellation — see the cleanup comment.
  const startLoop = (element: HTMLElement, animation: Animation) => {
    if (disposed) {
      return;
    }
    const group = getLoopAnimation(element, animation);
    if (!group) {
      return;
    }
    liveLoops.add(group);
    playWhileLive(group);
  };

  const observer = new IntersectionObserver(
    entries => {
      for (const entry of entries) {
        // a node that has only just touched the viewport stays observed, so the later
        // ENTRANCE_THRESHOLD crossing still arrives — unobserving here would strand it
        if (!entry.isIntersecting || !hasEntered(entry)) {
          continue;
        }
        const element = entry.target as HTMLElement;
        // once-semantics: each node's playback is triggered a single time
        observer.unobserve(element);

        const animation = byNodeId.get(element.dataset.ricosAnimation ?? '');
        if (!animation) {
          reveal(element);
          continue;
        }
        const entranceGroup = hasEntranceAnimation(animation)
          ? getEntranceAnimation(element, animation)
          : null;
        if (!entranceGroup) {
          // loop-only node, or an entrance this build can't map (fail open):
          // reveal and let any loop start immediately
          reveal(element);
          if (hasLoopAnimation(animation)) {
            startLoop(element, animation);
          }
          continue;
        }
        // The loop chains onto `finished`, never onto play() — motion's play() resolves as soon as
        // playback *starts* (it awaits each Animation's `ready`), and a loop begun there composites
        // over the still-running entrance: created second with WAAPI's default composite 'replace'
        // and `fill: 'both'`, it owns every property it declares, so the entrance runs invisibly
        // and the node appears to snap into place when the entrance's duration ends.
        // Read `finished` once, before play(), so no start/finish race is possible (motion's
        // getter builds a fresh promise per access). A cancelled or failed entrance rejects —
        // it must not spawn an infinite animation during teardown.
        const entranceFinished = entranceGroup.finished;
        entranceFinished.then(
          () => {
            if (hasLoopAnimation(animation)) {
              startLoop(element, animation);
            }
          },
          () => {}
        );
        // nothing awaits the start: `finished` above owns the chain, `ready` below the reveal.
        // The play gate is attached to `ready` before the reveal, so start and un-hide land
        // in the same microtask flush — no frame paints in between.
        playWhileLive(entranceGroup, () =>
          entranceFinishedByElement.set(element, entranceFinished)
        );
        entranceGroup.ready.then(() => reveal(element)).catch(() => reveal(element));
      }
    },
    { threshold: OBSERVER_THRESHOLDS }
  );

  elements.forEach(element => {
    const animation = byNodeId.get(element.dataset.ricosAnimation ?? '');

    // POINTER nodes skip the viewport machinery entirely: they were never hidden
    // (no entrance marker) and react to the cursor, not to scrolling. Register on
    // every init — a re-init's predecessor cancelled the instance on dispose.
    if (animation?.type === 'POINTER') {
      reveal(element);
      const instance = getPointerAnimation(element, animation);
      if (instance) {
        pointerManager ??= createPointerAnimationManager();
        pointerManager.register(instance);
      }
      return;
    }

    if (element.hasAttribute('data-ricos-entered')) {
      // content swaps re-init the runtime; entered nodes never replay their
      // entrance, but the previous runtime's cleanup cancelled their loop —
      // not restarting it here would freeze them for the rest of the session
      if (animation && hasLoopAnimation(animation)) {
        const entranceFinished = entranceFinishedByElement.get(element);
        if (entranceFinished) {
          // `data-ricos-entered` means the entrance *started*, not that it finished —
          // a swap can land mid-entrance, and dispose leaves that entrance playing on
          // this element. Starting the loop now would composite over it (see the chain
          // comment above), so the restart waits on the same `finished` the previous
          // runtime chained on. A long-settled promise restarts the loop immediately;
          // a rejected one must not spawn a loop, matching the first-run contract.
          entranceFinished.then(
            () => startLoop(element, animation),
            () => {}
          );
        } else {
          startLoop(element, animation);
        }
      }
      return;
    }
    observer.observe(element);
  });

  return () => {
    disposed = true;
    observer.disconnect();
    // cancel every running loop. Mid-flight entrances are deliberately left playing:
    // the animated elements survive content-swap re-renders, so cancelling would snap
    // them to their natural (final) state mid-animation — the next runtime picks the
    // sequence up via entranceFinishedByElement instead. On a real unmount the elements
    // leave the DOM and their animations become irrelevant with them. Loops can't get
    // that treatment: left untracked, an infinite animation would keep running with no
    // handle able to stop it, and the next runtime's restart would stack a second one
    // on top.
    liveLoops.forEach(group => group.cancel());
    // pointer instances hold no timeline to leave running — cancelling clears
    // their inline transforms and drops the window listener with them
    pointerManager?.dispose();
  };
};
