import type { ScrubAnimationOptions } from '@wix/motion';

import type {
  Animation,
  Animation_Easing,
  PointerEffect_Scale_Direction,
} from './../../ricos-schema/next-schema/index.js';
import { Animation_Type } from './../../ricos-schema/next-schema/index.js';

import type { PointerEffectConfig } from './pointer-effects.js';
import { POINTER_EFFECTS, SCALE_INTENSITY } from './pointer-effects.js';

const SCREAMING_ENUM = /^[A-Z][A-Z_]*$/;

// Schema enum params are SCREAMING_SNAKE; motion literals are kebab-lower
// (BOTH → 'both', CENTER_HORIZONTAL → 'center-horizontal') — same shape-test
// mapping as the other converters. `transitionEasing` must never pass through
// here: motion's values are lowerCamel (hardBackOut), not kebab. It isn't
// stored today (classic ships it undefined → motion falls back to 'linear');
// if it's ever exposed, give it an explicit map like EASING_TO_MOTION.
const toMotionParam = (value: unknown): unknown =>
  typeof value === 'string' && SCREAMING_ENUM.test(value)
    ? value.toLowerCase().replace(/_/g, '-')
    : value;

/**
 * Converts a stored `Animation`'s POINTER kind into `@wix/motion` scrub-animation options.
 * Same fail-open contract as the other converters: null for anything this build can't map.
 *
 * The result feeds `getAnimation(el, options, { trigger: 'pointer-move' })`, which returns a
 * `MouseAnimationInstance` — motion applies the CSS transition but attaches no listener;
 * ricos's pointer-animation-manager owns `pointermove` and feeds `instance.progress()`.
 */
export const toPointerMotionOptions = (animation: Animation): ScrubAnimationOptions | null => {
  if (animation.type !== Animation_Type.POINTER) {
    return null;
  }
  const { effect, transitionDuration } = animation;
  if (!effect) {
    return null;
  }
  const { type, ...storedParams } = effect;
  const config = POINTER_EFFECTS[type] as PointerEffectConfig | undefined;
  if (!config) {
    return null;
  }
  // stored values win, but an explicit `undefined` key must not clobber the default
  const params: Record<string, unknown> = {
    ...config.params,
    ...Object.fromEntries(Object.entries(storedParams).filter(([, value]) => value !== undefined)),
  };
  // Motion style scales the effect's intensity numeric (angle/scale/distance) rather than an
  // easing curve — pointer smoothing is the CSS transition, whose curve isn't stored (see
  // `toMotionParam`). `direction` is consumed here too rather than forwarded: it is SCALE's
  // only param with no motion counterpart (`ScaleMouse` takes a numeric `scale`), and the
  // numeric depends on it together with the motion style.
  const { easing, direction, ...effectParams } = params as {
    easing?: Animation_Easing;
    direction?: PointerEffect_Scale_Direction;
  };
  // An unknown stored motion style (newer build) remaps to MODERATE rather than being
  // dropped: without the ladder value the preset's own numeric applies, and motion's
  // defaults are unusably weak (Tilt3D angle 5° vs the editor's 50°).
  const style: Animation_Easing =
    easing && SCALE_INTENSITY[easing] !== undefined ? easing : 'MODERATE';
  const scaleFromDirection =
    type === 'SCALE'
      ? {
          scale: direction === 'UP' ? 1 + SCALE_INTENSITY[style] : 1 - SCALE_INTENSITY[style],
        }
      : {};

  return {
    namedEffect: {
      type: config.preset,
      ...config.motionParams,
      ...config.powerParams?.[style],
      ...scaleFromDirection,
      ...Object.fromEntries(
        Object.entries(effectParams).map(([key, value]) => [
          // one schema key, two motion options: SWIVEL's `axis` is a pivot edge/center
          // (motion's `pivotAxis`), everywhere else it's the movement axis
          key === 'axis' && type === 'SWIVEL' ? 'pivotAxis' : key,
          toMotionParam(value),
        ])
      ),
    },
    // `??`, not `||`: 0 is a real setting (the Velocity slider's floor), and motion composes no
    // CSS transition at all for it — the node tracks the pointer instantly. The entrance/loop
    // converters keep `||` for `duration`: there a 0 is an invisible animation, and their
    // slider floor is 0.1s.
    transitionDuration: transitionDuration ?? config.transitionDuration,
    // santa's envelope verbatim: progress is computed relative to the node's own center,
    // and fill both keeps the transform applied between pointer events
    centeredToTarget: true,
    fill: 'both',
  };
};
