import type {
  Animation_Easing,
  PointerEffect,
  PointerEffect_Type,
} from './../../ricos-schema/next-schema/index.js';

/** The optional params a given pointer effect owns, with its discriminant removed. */
export type PointerEffectParams<T extends PointerEffect_Type> = Omit<
  Extract<PointerEffect, { type: T }>,
  'type'
>;

export type PointerEffectConfig<T extends PointerEffect_Type = PointerEffect_Type> = {
  /** `@wix/motion-presets` preset this effect plays — must match a key registered in `motion-runtime`. */
  preset: string;
  /** Default settle time toward the pointer in ms (the classic velocity default). */
  transitionDuration: number;
  /**
   * Defaults for the effect's own params — `inverted`, `axis` (a movement axis, or SWIVEL's
   * pivot), `direction` and `easing` (motion style). Typed from the schema variant, so a
   * param the variant doesn't declare can't be given a default here.
   */
  params?: PointerEffectParams<T>;
  /**
   * Numeric preset params that are NOT in the schema (decision: minimal panel), fixed at
   * santa's classic values. Ricos must own these — motion's own defaults are unusably weak
   * (`Tilt3DMouse` defaults to a 5° angle where the Wix editor plays 50°).
   */
  motionParams?: Record<string, unknown>;
  /**
   * The numeric each motion style scales, merged over `motionParams` at conversion time.
   * MODERATE is anchored at the value the Wix editor ships for the effect's classic default
   * power (always medium for mouse); GENTLE/INTENSE step around it within the classic slider
   * range. Provisional pending a visual side-by-side with santa — config-local and
   * injected at play time, so retuning is retroactive. SCALE is absent:
   * its motion style interacts with `direction`, so the converter computes it.
   */
  powerParams?: Record<Animation_Easing, Record<string, unknown>>;
};

const angleLadder = (
  gentle: number,
  moderate: number,
  intense: number
): Record<Animation_Easing, Record<string, unknown>> => ({
  GENTLE: { angle: gentle },
  MODERATE: { angle: moderate },
  INTENSE: { angle: intense },
});

/**
 * The single source of truth for every ricos-owned mouse-effect default.
 *
 * Mirrors santa-editor's `@wix/effects-kit` classic-editor config (same recipe as
 * `ENTRANCE_EFFECTS` / `LOOP_EFFECTS`): `transitionDuration`, `inverted`, `axis` and
 * `direction` come from each effect's classic schema defaults; the numeric references come
 * from the responsive config's medium values, which is what the Wix editor actually plays
 * for the classic default power. The one deliberate divergence is SCALE's `axis` — see below.
 *
 * Defaults are injected at playback time rather than written into the document — see
 * `ENTRANCE_EFFECTS` for why.
 */
export const POINTER_EFFECTS: { [T in PointerEffect_Type]: PointerEffectConfig<T> } = {
  AIRY: {
    preset: 'AiryMouse',
    transitionDuration: 500,
    params: { inverted: false, axis: 'BOTH', easing: 'MODERATE' },
    motionParams: { distance: { value: 150, unit: 'px' } },
    powerParams: angleLadder(25, 50, 75),
  },
  BLOB: {
    preset: 'BlobMouse',
    transitionDuration: 350,
    params: { inverted: false, easing: 'MODERATE' },
    motionParams: { distance: { value: 150, unit: 'px' } },
    // Blob's intensity numeric is its scale (classic range 1–4, medium 1.6)
    powerParams: {
      GENTLE: { scale: 1.3 },
      MODERATE: { scale: 1.6 },
      INTENSE: { scale: 2.2 },
    },
  },
  BLUR: {
    preset: 'BlurMouse',
    transitionDuration: 500,
    params: { inverted: false, easing: 'MODERATE' },
    motionParams: { distance: { value: 100, unit: 'px' }, blur: 25, scale: 0.7 },
    powerParams: angleLadder(12, 25, 40),
  },
  SCALE: {
    preset: 'ScaleMouse',
    transitionDuration: 500,
    // `axis: HORIZONTAL` is the one deliberate departure from classic, which inherits
    // effects-kit's shared `both` (schema decision 6, 2026-08-05) — a product choice, not
    // a mirroring miss. The converter always emits it: motion falls back to `both` on an
    // absent axis, which would undo the choice.
    params: { inverted: false, axis: 'HORIZONTAL', direction: 'DOWN', easing: 'MODERATE' },
    motionParams: { distance: { value: 80, unit: 'px' } },
    // scale is computed in the converter from direction × motion style
  },
  SKEW: {
    preset: 'SkewMouse',
    transitionDuration: 250,
    params: { inverted: true, axis: 'BOTH', easing: 'MODERATE' },
    motionParams: { distance: { value: 80, unit: 'px' } },
    powerParams: angleLadder(12, 25, 38),
  },
  SWIVEL: {
    preset: 'SwivelMouse',
    transitionDuration: 500,
    // SWIVEL's `axis` is its pivot (its own enum), not a movement axis
    params: { inverted: false, axis: 'TOP', easing: 'MODERATE' },
    motionParams: { perspective: 1000 },
    powerParams: angleLadder(25, 50, 75),
  },
  TILT_3D: {
    preset: 'Tilt3DMouse',
    transitionDuration: 500,
    params: { inverted: false, easing: 'MODERATE' },
    motionParams: { perspective: 1000 },
    powerParams: angleLadder(25, 50, 75),
  },
  TRACK: {
    preset: 'TrackMouse',
    transitionDuration: 500,
    params: { inverted: false, axis: 'BOTH', easing: 'MODERATE' },
    // Track's only intensity numeric is its travel distance (classic medium 250px)
    powerParams: {
      GENTLE: { distance: { value: 125, unit: 'px' } },
      MODERATE: { distance: { value: 250, unit: 'px' } },
      INTENSE: { distance: { value: 400, unit: 'px' } },
    },
  },
  TRACK_3D: {
    preset: 'Track3DMouse',
    transitionDuration: 500,
    params: { inverted: true, axis: 'HORIZONTAL', easing: 'MODERATE' },
    motionParams: { distance: { value: 250, unit: 'px' }, perspective: 500 },
    powerParams: angleLadder(25, 50, 75),
  },
};

/**
 * How far SCALE moves from a scale of 1 per motion style; the stored `direction` decides
 * the sign (DOWN shrinks, UP grows). Anchored so classic's medium + DOWN plays the
 * editor's 0.5.
 */
export const SCALE_INTENSITY: Record<Animation_Easing, number> = {
  GENTLE: 0.25,
  MODERATE: 0.5,
  INTENSE: 0.75,
};

/**
 * The pointer effect's default motion style. Unlike entrance/loop, every mouse effect has
 * one (classic `power` is `medium` across the board), so this never returns undefined —
 * still, go through here rather than reading `.easing` off the params union.
 */
export const defaultPointerEasingOf = (type: PointerEffect_Type): Animation_Easing | undefined =>
  (POINTER_EFFECTS[type].params as { easing?: Animation_Easing } | undefined)?.easing;
