import type { AnimationGroup, MouseAnimationInstance } from '@wix/motion';
import { getAnimation, registerEffects } from '@wix/motion';
import {
  AiryMouse,
  ArcIn,
  BlobMouse,
  BlurIn,
  BlurMouse,
  Bounce,
  BounceIn,
  Breathe,
  Cross,
  DropIn,
  ExpandIn,
  FadeIn,
  Flash,
  Flip,
  FlipIn,
  FloatIn,
  Fold,
  FoldIn,
  GlideIn,
  Jello,
  Poke,
  Pulse,
  RevealIn,
  Rubber,
  ScaleMouse,
  ShapeIn,
  ShuttersIn,
  SkewMouse,
  SlideIn,
  Spin,
  SpinIn,
  Swing,
  SwivelMouse,
  Tilt3DMouse,
  TiltIn,
  Track3DMouse,
  TrackMouse,
  TurnIn,
  Wiggle,
  WinkIn,
} from '@wix/motion-presets';

import type { Animation } from './../../ricos-schema/next-schema/index.js';

import { toLoopMotionOptions } from './to-loop-motion-options.js';
import { toMotionOptions } from './to-motion-options.js';
import { toPointerMotionOptions } from './to-pointer-motion-options.js';

// The ONLY module that statically imports @wix/motion + @wix/motion-presets.
// It must be reached exclusively via dynamic import() (editor preview hook,
// viewer runtime chunk) so the motion runtime never enters an eager bundle.
// All 18 entrance + 13 ongoing + 9 mouse presets are registered: the viewer
// must play any effect stored in content, and the panel previews all of them.
registerEffects({
  ArcIn,
  BlurIn,
  Bounce,
  BounceIn,
  Breathe,
  Cross,
  DropIn,
  ExpandIn,
  FadeIn,
  Flash,
  Flip,
  FlipIn,
  FloatIn,
  Fold,
  FoldIn,
  GlideIn,
  Jello,
  Poke,
  Pulse,
  RevealIn,
  Rubber,
  ShapeIn,
  ShuttersIn,
  SlideIn,
  Spin,
  SpinIn,
  Swing,
  TiltIn,
  TurnIn,
  Wiggle,
  WinkIn,
});
// The mouse presets are bare create-factories (default exports), and motion's declared
// EffectModule union types the scrub-factory variant more narrowly than the presets'
// own generics — a declaration gap, not a runtime one: the registry is a flat map and
// getWebAnimationEffect calls `preset.web ? preset.web(...) : preset(...)`.
registerEffects({
  AiryMouse,
  BlobMouse,
  BlurMouse,
  ScaleMouse,
  SkewMouse,
  SwivelMouse,
  Tilt3DMouse,
  Track3DMouse,
  TrackMouse,
} as unknown as Parameters<typeof registerEffects>[0]);

/**
 * Creates a replayable entrance animation for a node's DOM element.
 * Returns a motion `AnimationGroup` (`play()` / `cancel()` / `pause()`), or
 * null when the target/options are invalid — including a stored animation this
 * build has no mapping for (see `toMotionOptions`). Callers reveal the node on
 * null rather than leaving it hidden.
 */
export const getEntranceAnimation = (
  element: HTMLElement,
  animation: Animation
): AnimationGroup | null => {
  const options = toMotionOptions(animation);
  if (!options) {
    return null;
  }
  const group = getAnimation(element, options);
  // no trigger passed → never a MouseAnimationInstance
  return (group as AnimationGroup | null) ?? null;
};

/**
 * Creates the looping animation for a node's DOM element — infinite by default
 * (motion's `iterations: 0` sentinel); the editor preview passes a small finite
 * count so the group's `finished` promise settles. Same null contract as
 * `getEntranceAnimation`.
 */
export const getLoopAnimation = (
  element: HTMLElement,
  animation: Animation,
  options: { iterations?: number } = {}
): AnimationGroup | null => {
  const motionOptions = toLoopMotionOptions(animation, options);
  if (!motionOptions) {
    return null;
  }
  const group = getAnimation(element, motionOptions);
  // no trigger passed → never a MouseAnimationInstance
  return (group as AnimationGroup | null) ?? null;
};

/**
 * Creates the pointer-driven animation for a node's DOM element. The returned
 * `MouseAnimationInstance` is already "playing" — meaning its CSS transition is
 * applied; actual movement only happens when the caller feeds `instance.progress()`
 * (motion attaches no pointer listener — the viewer's pointer-animation-manager and
 * the editor's preview sweep own that). `cancel()` clears the inline transform.
 * Same null contract as the other getters.
 */
export const getPointerAnimation = (
  element: HTMLElement,
  animation: Animation
): MouseAnimationInstance | null => {
  const motionOptions = toPointerMotionOptions(animation);
  if (!motionOptions) {
    return null;
  }
  const instance = getAnimation(element, motionOptions, { trigger: 'pointer-move' });
  // the pointer-move trigger with a namedEffect always yields a MouseAnimationInstance
  return (instance as MouseAnimationInstance | null) ?? null;
};
