import type { TimeAnimationOptions } from '@wix/motion';

import type {
  Animation,
  Animation_Easing,
  Animation_RadialDirection,
  EntranceAnimation,
  EntranceEffect_Glide_Direction,
} from './../../ricos-schema/next-schema/index.js';
import { Animation_Type } from './../../ricos-schema/next-schema/index.js';

import type { EntranceEffectConfig } from './entrance-effects.js';
import { ENTRANCE_EFFECTS } from './entrance-effects.js';

/** Ricos-canonical motion-style vocabulary → motion easing curve names. */
const EASING_TO_MOTION: Record<Animation_Easing, string> = {
  GENTLE: 'cubicOut',
  MODERATE: 'cubicInOut',
  INTENSE: 'backOut',
};

const SCREAMING_ENUM = /^[A-Z][A-Z_]*$/;

// Schema enum params are SCREAMING_SNAKE; motion literals are kebab-lower
// (TOP_LEFT → 'top-left', COUNTER_CLOCKWISE → 'counter-clockwise').
// Non-enum values pass through unchanged.
//
// The shape test stands in for a per-key mapping because every string param the
// entrance union declares today (`direction`, `shape`) is a schema enum, and no
// effect takes a free-text string. Add a per-key mapping the moment one does —
// an all-caps non-enum value (an id, a token) would be silently kebab-cased here.
const toMotionParam = (value: unknown): unknown =>
  typeof value === 'string' && SCREAMING_ENUM.test(value)
    ? value.toLowerCase().replace(/_/g, '-')
    : value;

/**
 * `ExpandIn` and `GlideIn` take a numeric angle rather than a direction keyword, so the compass
 * values their schema variants offer have to be translated. Motion derives its offset as
 * `x = cos(angle) · distance`, `y = -sin(angle) · distance`, i.e. the angle names the origin.
 */
const DIRECTION_TO_ANGLE: Record<EntranceEffect_Glide_Direction, number> = {
  RIGHT: 0,
  TOP_RIGHT: 45,
  TOP: 90,
  TOP_LEFT: 135,
  LEFT: 180,
  BOTTOM_LEFT: 225,
  BOTTOM: 270,
  BOTTOM_RIGHT: 315,
};

/**
 * Effects whose schema params don't map 1:1 onto their motion preset's params.
 * Everything else passes through `toMotionParam` unchanged.
 */
const adaptParams = (
  type: keyof typeof ENTRANCE_EFFECTS,
  params: Record<string, unknown>
): Record<string, unknown> => {
  if (type === 'EXPAND' || type === 'GLIDE') {
    const direction = params.direction as Animation_RadialDirection;
    return direction === 'CENTER'
      ? // `CENTER` (EXPAND only — GLIDE's variant has no such value) has no angle;
        // zeroing the travel distance degrades ExpandIn to a pure scale-up + fade in place
        { distance: { value: 0, unit: 'percentage' } }
      : { direction: DIRECTION_TO_ANGLE[direction] };
  }
  return Object.fromEntries(
    Object.entries(params).map(([key, value]) => [key, toMotionParam(value)])
  );
};

/**
 * Converts a stored `Animation` into `@wix/motion` time-animation options
 * for entrance playback. The canonical schema → runtime mapping (see ADR-003).
 *
 * Returns null for anything this build can't map. Content outlives the code that
 * reads it — kinds and effects are added additively (a viewer predating the mouse
 * family already meets `POINTER` documents), so an older viewer *will* meet values
 * it has no mapping for, and the types below describe the schema this build was
 * compiled against, not what's in the document. Callers must fail open on null
 * (reveal the node): throwing here would
 * escape the viewer's IntersectionObserver callback and leave content hidden forever.
 */
export const toMotionOptions = (animation: Animation): TimeAnimationOptions | null => {
  if (animation.type !== Animation_Type.VIEW) {
    return null;
  }
  // loop-only VIEW animations land here too — this mapper owns entrance alone
  const entrance: EntranceAnimation | undefined = animation.entrance;
  if (!entrance?.effect) {
    return null;
  }
  const { effect, duration, delay } = entrance;
  const { type, ...storedParams } = effect;
  const config = ENTRANCE_EFFECTS[type] as EntranceEffectConfig | undefined;
  if (!config) {
    return null;
  }
  // stored values win, but an explicit `undefined` key must not clobber the
  // default — motion would then fall back to its own (differing) default
  const params: Record<string, unknown> = {
    ...config.params,
    ...Object.fromEntries(Object.entries(storedParams).filter(([, value]) => value !== undefined)),
  };
  // motion style is an effect property in the schema but a top-level motion option, so it's split
  // out before `adaptParams` (whose EXPAND/GLIDE branches rebuild the params object from scratch).
  // Effects with no motion style leave it unset, so motion's own built-in curve plays.
  const { easing, ...effectParams } = params as { easing?: Animation_Easing };
  return {
    namedEffect: {
      type: config.preset,
      ...adaptParams(type, effectParams),
    },
    // `||`, not `??`: the schema's uint32 admits a stored 0, which motion coerces to a 1ms
    // animation nobody can see. Treat it like an omitted value and use the effect's default.
    duration: duration || config.duration,
    ...(delay !== undefined ? { delay } : {}),
    // an easing this build doesn't know is dropped, not forwarded as undefined —
    // motion's own built-in curve is a better fallback than no curve at all
    ...(easing && EASING_TO_MOTION[easing] ? { easing: EASING_TO_MOTION[easing] } : {}),
    // hold the first keyframe from the moment playback starts until the delay is up (an idle
    // animation applies nothing, so this is about `delay`, not about creation), and the final
    // (natural) state after finish — no flash on preview replays, and a loop chained onto the
    // finish takes over from that held state
    fill: 'both',
  };
};
