import type { MouseAnimationInstance } from '@wix/motion';

export type PointerAnimationManager = {
  /**
   * Adds an instance to the fan-out and starts tracking whether it is on screen;
   * attaches the window listener on the first one.
   */
  register: (instance: MouseAnimationInstance) => void;
  /**
   * Cancels every instance (clearing its inline transform) and removes the listener
   * and the visibility observer.
   */
  dispose: () => void;
};

/**
 * The single pointer driver for one viewer runtime: motion's `MouseAnimationInstance`
 * exposes only `progress({x, y})` and attaches no listener of its own, so ricos owns
 * one window-level `pointermove` listener, rAF-throttled, fanning normalized progress
 * out to every registered instance.
 *
 * Coordinates are centered-to-target (matching santa's `centeredToTarget: true` and
 * interact's pointer trigger): `{x: 0.5, y: 0.5}` means the pointer is at the node's
 * own center, and deviation is normalized by the viewport size — so a node reacts most
 * strongly when the cursor is near it, wherever it sits on the page. Rects are read
 * for all instances before any `progress()` write applies a transform, keeping the
 * frame free of layout thrash.
 *
 * Only on-screen instances are measured: an article can carry dozens of animated nodes,
 * and a rect read per node per cursor frame is a cost the reader pays for nodes they
 * can't see.
 */
// motion's Progress contract is 0..1 (0.5 = neutral). Centered-to-target values can
// leave that range when the cursor is up to a full viewport away from the node's
// center — unclamped, a Tilt3D capped at 50° would visibly fold past 90°.
const clamp01 = (value: number) => Math.min(1, Math.max(0, value));

/** Neutral progress — the pose a node holds when the pointer sits on its own center. */
const CENTER = { x: 0.5, y: 0.5 };

export const createPointerAnimationManager = (): PointerAnimationManager => {
  // the observer reports targets, so the instance has to be reachable from its element
  const byTarget = new Map<Element, MouseAnimationInstance>();
  const onScreen = new Set<MouseAnimationInstance>();
  let lastEvent: PointerEvent | null = null;
  let frame = 0;
  let listening = false;

  // Unlike the entrance observer, this one has no once-semantics: it has to keep reporting
  // as nodes scroll back out. A node leaving is eased to neutral once — otherwise it would
  // scroll back in frozen in whatever pose the cursor last left it, then unfreeze.
  const observer =
    typeof IntersectionObserver === 'undefined'
      ? null
      : new IntersectionObserver(entries => {
          for (const entry of entries) {
            const instance = byTarget.get(entry.target);
            if (!instance) {
              continue;
            }
            if (entry.isIntersecting) {
              onScreen.add(instance);
            } else if (onScreen.delete(instance)) {
              instance.progress(CENTER);
            }
          }
        });

  const applyFrame = () => {
    frame = 0;
    const event = lastEvent;
    if (!event) {
      return;
    }
    // read every rect first, then write every progress — reads after the first
    // transform write would force layout per instance
    const measured = Array.from(onScreen, instance => {
      const rect = instance.target.getBoundingClientRect();
      return {
        instance,
        x: clamp01(0.5 + (event.clientX - (rect.left + rect.width / 2)) / window.innerWidth),
        y: clamp01(0.5 + (event.clientY - (rect.top + rect.height / 2)) / window.innerHeight),
      };
    });
    measured.forEach(({ instance, x, y }) => instance.progress({ x, y }));
  };

  const onPointerMove = (event: PointerEvent) => {
    lastEvent = event;
    if (!frame) {
      frame = requestAnimationFrame(applyFrame);
    }
  };

  return {
    register: instance => {
      byTarget.set(instance.target, instance);
      // optimistic: the observer's first callback is a frame or two away, and a node that
      // is already on screen must not sit out the moves that land in between
      onScreen.add(instance);
      observer?.observe(instance.target);
      if (!listening) {
        listening = true;
        window.addEventListener('pointermove', onPointerMove, { passive: true });
      }
    },
    dispose: () => {
      if (frame) {
        cancelAnimationFrame(frame);
        frame = 0;
      }
      if (listening) {
        listening = false;
        window.removeEventListener('pointermove', onPointerMove);
      }
      observer?.disconnect();
      byTarget.forEach(instance => instance.cancel());
      byTarget.clear();
      onScreen.clear();
      lastEvent = null;
    },
  };
};
